import { EDiffLine, type DiffLine } from '@dltech/atlas-core'
import type { TextChunk } from '@opentui/core'
import { useEffect, useMemo, useRef, useState } from 'react'

import {
  cachedHighlight,
  highlightRows,
  type HighlightedRows,
} from '../../markdown/highlight-rows'
import type { DiffSpan } from './chunk-styling'

export type DiffEmphasis = (line: DiffLine) => DiffSpan | null

export type LineChunks = readonly (readonly TextChunk[] | null)[]

type Side = { texts: readonly string[]; rows: readonly number[] }

function sideOf(args: { lines: readonly DiffLine[]; skip: EDiffLine }): Side {
  const texts: string[] = []
  const rows: number[] = []
  args.lines.forEach((line, index) => {
    if (line.kind === EDiffLine.Elision || line.kind === args.skip) return
    rows.push(index)
    texts.push(line.text)
  })
  return { texts, rows }
}

function fill(args: {
  out: (readonly TextChunk[] | null)[]
  side: Side
  rows: HighlightedRows
}): void {
  if (args.rows === null) return
  args.side.rows.forEach((line, index) => {
    args.out[line] = args.rows?.[index] ?? null
  })
}

function assemble(args: {
  lines: readonly DiffLine[]
  older: { side: Side; rows: HighlightedRows }
  newer: { side: Side; rows: HighlightedRows }
}): LineChunks {
  const out: (readonly TextChunk[] | null)[] = args.lines.map(() => null)
  fill({ out, side: args.older.side, rows: args.older.rows })
  fill({ out, side: args.newer.side, rows: args.newer.rows })
  return out
}

function keyOf(args: { lines: readonly DiffLine[]; filetype: string }): string {
  return `${args.filetype}�${args.lines.map((line) => `${line.kind}${line.text}`).join('\n')}`
}

/**
 * A hunk is highlighted twice — once as the file was, once as it will be — because feeding
 * tree-sitter the interleaved rows would have it parse every changed line twice over, in two
 * contradictory versions of the same statement.
 */
export function useDiffChunks(args: {
  lines: readonly DiffLine[]
  filetype: string
}): LineChunks {
  const { lines, filetype } = args

  const sides = useMemo(
    () => ({
      older: sideOf({ lines, skip: EDiffLine.Added }),
      newer: sideOf({ lines, skip: EDiffLine.Removed }),
    }),
    [lines],
  )

  const key = useMemo(() => keyOf({ lines, filetype }), [lines, filetype])

  const cached = useMemo(
    () =>
      assemble({
        lines,
        older: {
          side: sides.older,
          rows: cachedHighlight({ lines: sides.older.texts, filetype }) ?? null,
        },
        newer: {
          side: sides.newer,
          rows: cachedHighlight({ lines: sides.newer.texts, filetype }) ?? null,
        },
      }),
    [lines, sides, filetype],
  )

  const [settled, setSettled] = useState<{ key: string; chunks: LineChunks } | null>(null)
  const latest = useRef({ lines, sides, filetype })
  latest.current = { lines, sides, filetype }

  useEffect(() => {
    const { lines, sides, filetype } = latest.current
    const older = cachedHighlight({ lines: sides.older.texts, filetype })
    const newer = cachedHighlight({ lines: sides.newer.texts, filetype })
    if (older !== undefined && newer !== undefined) return

    let live = true
    void Promise.all([
      highlightRows({ lines: sides.older.texts, filetype }),
      highlightRows({ lines: sides.newer.texts, filetype }),
    ]).then(([older, newer]) => {
      if (!live) return
      setSettled((current) =>
        current !== null && current.key === key
          ? current
          : {
              key,
              chunks: assemble({
                lines,
                older: { side: sides.older, rows: older },
                newer: { side: sides.newer, rows: newer },
              }),
            },
      )
    })
    return () => {
      live = false
    }
  }, [key])

  return settled !== null && settled.key === key ? settled.chunks : cached
}
