import { RGBA, StyledText, type TextChunk } from '@opentui/core'

import { mixHex } from './colour'
import { beaconHeat, shimmerCrest, WORKING_SHIMMER } from './shimmer'
import { SHIMMER_CREST } from './shimmer-style'
import { spinnerFrame, theme } from './theme'

export const SHIMMER_TICK_MS = 40

const TEXT_OFFSET = 2

const rgba = new Map<string, RGBA>()

const mixed = new Map<string, string>()

function colourOf(args: { heat: number; base: string }): string {
  const key = `${args.base}�${args.heat}`
  const held = mixed.get(key)
  if (held !== undefined) return held
  const next = mixHex({ from: args.base, to: SHIMMER_CREST, amount: args.heat })
  mixed.set(key, next)
  return next
}

function rgbaOf(hex: string): RGBA {
  const held = rgba.get(hex)
  if (held !== undefined) return held
  const next = RGBA.fromHex(hex)
  rgba.set(hex, next)
  return next
}

/**
 * The same spans the line always drew, as one StyledText: the heat curve over the label is a few
 * colours repeated along the crest, so they are cached by (base, heat) and a tick is the string
 * walk rather than a re-mix per character.
 */
export function shimmerText(args: {
  label: string
  base?: string | undefined
  now: number
}): StyledText {
  const base = args.base ?? theme.accent
  const cells = [...args.label].length + TEXT_OFFSET
  const crest = shimmerCrest({ nowMs: args.now, cells, spec: WORKING_SHIMMER })
  const chunks: TextChunk[] = [
    {
      __isChunk: true,
      text: spinnerFrame(args.now),
      fg: rgbaOf(colourOf({ heat: beaconHeat({ crest, spec: WORKING_SHIMMER }), base })),
    },
    { __isChunk: true, text: ' ' },
  ]
  let pending = ''
  let pendingFg: RGBA | null = null
  for (const [index, character] of [...args.label].entries()) {
    const heat = Math.max(0, 1 - Math.abs(index + TEXT_OFFSET - crest) / WORKING_SHIMMER.crestWidth)
    const fg = rgbaOf(colourOf({ heat, base }))
    if (pendingFg === fg) {
      pending += character
      continue
    }
    if (pendingFg !== null) chunks.push({ __isChunk: true, text: pending, fg: pendingFg })
    pending = character
    pendingFg = fg
  }
  if (pendingFg !== null) chunks.push({ __isChunk: true, text: pending, fg: pendingFg })
  return new StyledText(chunks)
}
