import {
  type SaidImage,
  attributedStop,
  EAgentStatus,
  type AssistantPart,
  type EKilledBy,
  type EMessageOrigin,
  type EventDraft,
  type ProviderIdentity,
  type RosteredAgent,
  type ThreadId,
} from '@dltech/atlas-core'

import type { AgentSnapshot, ChildContext } from './snapshot'

export type ChildState = {
  agentId: ThreadId
  spawnedBy: ThreadId
  agentType: string
  intent: string
  status: EAgentStatus
  killedBy: EKilledBy | undefined
  turns: number
  toolCalls: number
  lastTool: string | undefined
  lastText: string
  lastFullText: string
  startedAt: string
  steppingSince: string | undefined
  endedAt: string | undefined
  deliveredAt: string | undefined
  abort: AbortController
  pending: SteerMessage[]
  context: ChildContext | undefined
  model: ProviderIdentity | undefined
  projectDirectory: string | undefined
}

export type SteerMessage = {
  text: string
  images?: readonly SaidImage[] | undefined
  via?: EMessageOrigin | undefined
}

export const LAST_TEXT_TAIL_CHARACTERS = 4_000

export const boundedTail = (text: string): string =>
  text.length <= LAST_TEXT_TAIL_CHARACTERS ? text : text.slice(-LAST_TEXT_TAIL_CHARACTERS)

export const isStepping = (child: ChildState): boolean => child.status === EAgentStatus.Running

export function freshChild({
  agentId,
  spawnedBy,
  agentType,
  intent,
  at,
  projectDirectory,
}: {
  agentId: ThreadId
  spawnedBy: ThreadId
  agentType: string
  intent: string
  at: string
  projectDirectory: string | undefined
}): ChildState {
  return {
    agentId,
    spawnedBy,
    agentType,
    intent,
    status: EAgentStatus.Running,
    killedBy: undefined,
    turns: 0,
    toolCalls: 0,
    lastTool: undefined,
    lastText: '',
    lastFullText: '',
    startedAt: at,
    steppingSince: undefined,
    endedAt: undefined,
    deliveredAt: undefined,
    abort: new AbortController(),
    pending: [],
    context: undefined,
    model: undefined,
    projectDirectory,
  }
}

export function recoveredChild({
  agent,
  spawnedBy,
  at,
}: {
  agent: RosteredAgent
  spawnedBy: ThreadId
  at: string
}): ChildState {
  return {
    agentId: agent.agentId,
    spawnedBy,
    agentType: agent.agentType,
    intent: agent.intent,
    status: agent.status,
    killedBy: agent.killedBy,
    turns: agent.turns,
    toolCalls: agent.toolCalls,
    lastTool: undefined,
    lastText: boundedTail(agent.prose),
    lastFullText: agent.prose,
    startedAt: agent.spawnedAt ?? at,
    steppingSince: undefined,
    endedAt: agent.endedAt,
    deliveredAt: undefined,
    abort: new AbortController(),
    pending: [],
    context: undefined,
    model: undefined,
    projectDirectory: undefined,
  }
}

export function snapshotOf(child: ChildState): AgentSnapshot {
  return {
    agentId: child.agentId,
    spawnedBy: child.spawnedBy,
    agentType: child.agentType,
    intent: child.intent,
    status: child.status,
    killedBy: attributedStop({ status: child.status, killedBy: child.killedBy }),
    turns: child.turns,
    toolCalls: child.toolCalls,
    lastTool: child.lastTool,
    startedAt: child.startedAt,
    ...(child.steppingSince === undefined ? {} : { steppingSince: child.steppingSince }),
    endedAt: child.endedAt,
    deliveredAt: child.deliveredAt,
    context: child.context,
    model: child.model,
  }
}

export function agentEndedDraft(child: ChildState): EventDraft {
  return {
    type: 'agent-ended',
    agentId: child.agentId,
    agentType: child.agentType,
    intent: child.intent,
    status: child.status,
    killedBy: attributedStop({ status: child.status, killedBy: child.killedBy }),
    prose: child.lastFullText,
    turns: child.turns,
    toolCalls: child.toolCalls,
  }
}

const spokenText = (parts: readonly AssistantPart[]): string =>
  parts
    .filter((part) => part.type === 'text')
    .map((part) => part.text)
    .join('\n')
    .trim()

export function recordContext({
  child,
  tokens,
  window,
}: {
  child: ChildState
  tokens: number
  window: number
}): void {
  child.context = { tokens, window }
}

export function recordProgress({
  child,
  drafts,
}: {
  child: ChildState
  drafts: readonly EventDraft[]
}): void {
  for (const draft of drafts) {
    if (draft.type === 'assistant-said') {
      child.turns += 1
      const said = spokenText(draft.parts)
      if (said !== '') {
        child.lastText = boundedTail(said)
        child.lastFullText = said
      }
      continue
    }

    if (draft.type === 'tool-called') {
      child.toolCalls += 1
      child.lastTool = draft.name
    }
  }
}
